package puppetdb

import (
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/prometheus/common/model"

	promlabels "github.com/prometheus/prometheus/model/labels"
	"github.com/prometheus/prometheus/util/strutil"
)

type Resource struct {
	Certname    string     `json:"certname"`
	Resource    string     `json:"resource"`
	Type        string     `json:"type"`
	Title       string     `json:"title"`
	Exported    bool       `json:"exported"`
	Tags        []string   `json:"tags"`
	File        string     `json:"file"`
	Environment string     `json:"environment"`
	Parameters  Parameters `json:"parameters"`
}

type Parameters map[string]interface{}

func (p *Parameters) toLabels() model.LabelSet {
	params := make(Parameters, len(*p))
	for key, val := range *p {
		params[key] = val
	}
	keys := make([]string, 0, len(params))
	for name := range params {
		keys = append(keys, name)
	}
	if len(keys) > 1 {
		sort.Strings(keys)
	}

	pending := make(map[string]string, len(params))
	labelNameChars := [utf8.RuneSelf]bool{}
	for c := byte('a'); c <= 'z'; c++ {
		labelNameChars[c] = true
	}
	for c := byte('A'); c <= 'Z'; c++ {
		labelNameChars[c] = true
	}
	for c := byte('0'); c <= '9'; c++ {
		labelNameChars[c] = true
	}
	labelNameChars['_'] = true

	for _, k := range keys {
		v := params[k]
		var labelValue string
		switch value := v.(type) {
		case string:
			labelValue = value
		case bool:
			labelValue = strconv.FormatBool(value)
		case []string:
			labelValue = separator + strings.Join(value, separator) + separator
		case []interface{}:
			if len(value) == 0 {
				continue
			}
			values := make([]string, len(value))
			for i, v := range value {
				switch value := v.(type) {
				case string:
					values[i] = value
				case bool:
					values[i] = strconv.FormatBool(value)
				case []string:
					values[i] = separator + strings.Join(value, separator) + separator
				}
			}
			if len(values) == 1 {
				labelValue = values[0]
			} else {
				n := len(separator) * (len(values) - 1)
				for i := 0; i < len(values); i++ {
					n += len(values[i])
				}
				var joined strings.Builder
				joined.Grow(n)
				joined.WriteString(values[0])
				for _, part := range values[1:] {
					joined.WriteString(separator)
					joined.WriteString(part)
				}
				labelValue = joined.String()
			}
		case map[string]interface{}:
			if len(value) == 0 {
				continue
			}
			rawPrefix := k + "_"
			runeCount := 0
			remaining := rawPrefix
			for len(remaining) > 0 {
				_, width := utf8.DecodeRuneInString(remaining)
				runeCount++
				remaining = remaining[width:]
			}
			var prefixBuilder strings.Builder
			prefixBuilder.Grow(runeCount)
			idx := 0
			for idx < len(rawPrefix) {
				r, width := utf8.DecodeRuneInString(rawPrefix[idx:])
				if r < utf8.RuneSelf {
					if labelNameChars[byte(r)] {
						prefixBuilder.WriteByte(byte(r))
					} else {
						prefixBuilder.WriteByte('_')
					}
				} else {
					prefixBuilder.WriteByte('_')
				}
				idx += width
			}
			prefix := prefixBuilder.String()
			subParameter := Parameters(value)
			nested := subParameter.toLabels()
			if len(nested) == 0 {
				continue
			}
			for subk, subv := range nested {
				full := string(model.LabelName(prefix) + subk)
				pending[full] = string(subv)
			}
		default:
			continue
		}
		if labelValue == "" {
			continue
		}
		name := strutil.SanitizeLabelName(k)
		pending[name] = labelValue
	}

	converted := promlabels.FromMap(pending)
	normalized := converted.Map()
	result := make(model.LabelSet, len(normalized))
	if len(normalized) == 0 {
		return result
	}
	names := make([]string, 0, len(normalized))
	for name := range normalized {
		names = append(names, name)
	}
	if len(names) > 1 {
		sort.Strings(names)
	}
	for _, name := range names {
		result[model.LabelName(name)] = model.LabelValue(normalized[name])
	}
	return result
}

